def _cmd_convert(args: argparse.Namespace) -> int:
    moment = parse_iso(args.timestamp, assume=args.source)
    if args.source and moment.tzinfo is not None and moment.tzinfo != timezone.utc:
        pass
    line = f"{'source':<32} {_format(moment)}"
    print(line)
    source_value = moment
    for zone in args.targets:
        print(f"{zone:<32} {_format(convert(source_value, zone))}")
    return 0

